// _float_keysizeCoord returns the length of the encoding of the Coord that m
// points at, as the projection of a map key, which writes every float component
// of -0.0 as +0.0.
func _float_keysizeCoord(m *Coord) int {
	n := 0
	if m.Lat != 0 {
		n += 9
	}
	if m.Lon != 0 {
		n += 5
	}
	if _float_keypresentArray2Float64(&m.Span) {
		n += 18
	}
	return n
}

// _float_keysizeArray2Coord returns the length of the encoding of the elements
// of x, a [2]Coord, as the projection of a map key, which writes every float
// component of -0.0 as +0.0.
func _float_keysizeArray2Coord(x *[2]Coord) int {
	n := 0
	for k := range x {
		n += wire.SizeBytes(_float_keysizeCoord(&x[k]))
	}
	return n
}

