// _float_keysizePtrFloat64 returns the length of the encoding of x, a *float64,
// as the projection of a map key, which writes every float component of -0.0 as
// +0.0: its presence byte and the value that it points at.
func _float_keysizePtrFloat64(x *float64) int {
	if x == nil {
		return 1
	}
	return 9
}

// _float_comparePtrFloat64 returns -1, 0 or +1 as the map key a sorts before,
// with or after b, two keys of type *float64.
func _float_comparePtrFloat64(a, b *float64) int {
	if a == nil || b == nil {
		return wire.CompareBool(a != nil, b != nil)
	}
	return cmp.Compare(*a, *b)
}

// _float_nanPtrFloat64 reports whether x, a map key of type *float64, has a NaN
// component, which makes the key invalid.
func _float_nanPtrFloat64(x *float64) bool {
	return x != nil && *x != *x
}

// _float_keyputPtrFloat64 writes the encoding of x, a *float64, as the
// projection of a map key, which writes every float component of -0.0 as +0.0,
// into the end of buf, which has room for it, and returns its length.
func _float_keyputPtrFloat64(buf []byte, x *float64) int {
	i := len(buf)
	if x != nil {
		i = wire.PutUint64(buf, i, wire.KeyFloat64(*x))
	}
	i = wire.PutBool(buf, i, x != nil)
	return len(buf) - i
}

// _float_compareGauge returns -1, 0 or +1 as the map key a sorts before, with
// or after b, two keys of type Gauge.
func _float_compareGauge(a, b Gauge) int {
	if c := wire.CompareComplex(complex128(a.Phase), complex128(b.Phase)); c != 0 {
		return c
	}
	return wire.CompareComplex(a.Wave, b.Wave)
}

// _float_nanGauge reports whether x, a map key of type Gauge, has a NaN
// component, which makes the key invalid.
func _float_nanGauge(x Gauge) bool {
	return x.Phase != x.Phase || x.Wave != x.Wave
}

// _float_keyputGauge writes the encoding of the Gauge that m points at, as the
// projection of a map key, which writes every float component of -0.0 as +0.0,
// into the end of buf, which has room for it, and returns its length.
