// and reuses its memory, as DecodeKanon does. data starts at offset off of
// slab, and the decode enters depth levels below the value at most.
func _float_readCoord(m *Coord, data []byte, slab string, off, depth int) error {
	m.Lat = 0
	m.Lon = 0
	m.Span = [2]float64{}
	return _float_mergeCoord(m, data, slab, off, depth)
}

// _float_readArray2Coord decodes the elements that data encodes, a [2]Coord
// without its length, into *dst. It fails unless data encodes exactly 2
// elements. data starts at offset off of slab, and the decode enters depth
// levels below the value at most. loc and num locate the field in errors.
func _float_readArray2Coord(dst *[2]Coord, data []byte, slab string, off, depth int, loc string, num int) error {
	i := 0
	for k := range dst {
		l, n := wire.Uvarint(data[i:])
		if n <= 0 || uint64(len(data)-i-n) < l {
			return wire.ReadError(n, loc, num, off+i)
		}
		i += n
		if depth < 0 {
			return wire.DepthError("Coord", 0, off+i)
		}
		if err := _float_readCoord(&dst[k], data[i:i+int(l)], slab, off+i, depth); err != nil {
			return err
		}
		i += int(l)
	}
	if i != len(data) {
		return wire.TrailingError(len(data)-i, loc, num, off+i)
	}
	return nil
}

